# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
G=[['希腊 psyche（ψυχή）','生命、灵魂、心灵；在不同思想传统中含义有变化']]
P=G+[['拉丁 psyche → 英语 psyche','灵魂、精神 → 一个人的内心世界']]
C=G+[['希腊 psychikos；英语 psychical／psychic','心灵方面的 → 心理的；也用于所谓超感知能力']]
J=G+[['psyche 与希腊 iatros／iatreia 等医学构词材料','心灵 + 医者、治疗'],['法语 psychiatrie 等近代欧洲术语 → 英语 psychiatry','研究、诊治精神与心理障碍的医学分支']]
Y=G+[['近代 psychology 等英语心理词汇','心理学、心理活动方面的词'],['英语截短词 psych','心理相关简称；影响或准备心理状态']]
def H(h,w,m):return h+[[w,m]]
WA=[
E('psyche','/ˈsaɪki/','心灵；精神；内心世界','不是眼睛看得见的身体，而是一个人怎样想、怎样感受、怎样理解自己的整个内在世界。','借自拉丁 psyche，接希腊 psyche“灵魂、生命、心灵”；末尾 e 在英语中要读出来。',P,'the human psyche 说人的心灵；a character’s psyche 可以说小说人物深层的愿望、恐惧与矛盾。在古代文本中，它可能保留“灵魂”之义；在现代心理或文学讨论中，常指心智和内心活动。','the human psyche；the collective psyche；explore someone’s psyche。','psyche 读两个音节 /ˈsaɪki/；psych 这个截短词只有 /saɪk/。mind 更日常，psyche 常显得较深入、书面。',('The novel explores the troubled psyche of its narrator.','小说探入叙述者充满矛盾的内心世界。'),('The event left a lasting mark on the nation’s psyche.','这件事在这个国家的集体心理上留下了长久印记。'),sources=['https://www.etymonline.com/word/psyche','https://en.wiktionary.org/wiki/psyche']),
E('psychic','/ˈsaɪkɪk/','心灵的；所谓有超感知能力的；声称有这类能力的人','一条意思谈人的内心活动，另一条意思谈声称能读心、预知等超常能力的人。','接希腊 psychikos“心灵、灵魂方面的”；英语还有更早的相关形式 psychical。',C,'a psychic experience 在通灵故事里常指超常体验；a psychic 作名词常指灵媒或声称有特殊感知的人。较专业或较旧的 psychic energy 也可能只是某种理论中的心理能量。这个词表达一种称呼或主张，并不自动证明超能力存在。','psychic abilities；a psychic reading；psychic energy。','psychic 不是 psychiatrist“精神科医生”。psychic 的超常能力义与 scientific psychology“科学心理学”也不能混为一谈。',('The character claims to have psychic abilities.','这个角色声称自己有超感知能力。'),('The article examines why people consult a psychic.','文章考察了人们为什么会去咨询灵媒。'),sources=['https://www.etymonline.com/word/psychic','https://en.wiktionary.org/wiki/psychic']),
E('psychical','/ˈsaɪkɪkəl/','心理的；心灵方面的；所谓超自然心灵现象的〔较书面〕','把镜头朝向心灵或精神活动，有时也朝向被称作通灵、超感知的现象。','接希腊 psychikos 与形容词成分 -al；英语 psychical 的使用早于现代常见 psychic。',C,'旧式心理学文字中的 psychical processes 可以是一般心理过程；psychical research 这一历史名称则常指研究通灵、心灵感应等主张的领域。两种用法共用词形，要由搭配辨认范围。','psychical processes；psychical experience；psychical research。','psychical 与 psychic 大量重叠，但 psychological 更常用来明确表示一般心理学或心理方面的意思。',('The old textbook distinguished physical and psychical processes.','这本旧教材区分了身体过程与心理过程。'),('The museum displays documents from the history of psychical research.','博物馆展示了超常心灵现象研究史上的文献。'),sources=['https://www.etymonline.com/word/psychic','https://en.wiktionary.org/wiki/psychical']),
E('psychically','/ˈsaɪkɪkli/','在心理上；以所谓心灵感应的方式','说明一件事发生在内心层面，或某人声称自己靠超常心灵能力做到了它。','与 psychic／psychical 对应的 -ly 副词形式，读音中通常不另读出一个完整的 -al- 音节。',H(C,'英语 psychic／psychical 对应副词 psychically','心灵方面的 → 在心灵层面、以所谓心灵感应方式'),'psychically connected 在奇幻故事里可能是两人可以隔空交流；较旧的学术语境也可用 psychically 说心理上受到影响。普通表达心理影响时，psychologically 通常更清楚。','psychically connected；communicate psychically。','psychically 的语境可能含超自然主张；psychologically 一般明确指心理层面，不包含这种主张。',('In the story, the twins communicate psychically across great distances.','故事中，这对双胞胎能隔着很远的距离以心灵感应交流。'),('The witness claimed to have sensed the event psychically.','那位证人声称自己通过心灵感应察觉了那件事。'),sources=['https://en.wiktionary.org/wiki/psychically','https://www.etymonline.com/word/psychic']),
E('psych','/saɪk/','影响心理；使作好心理准备；心理学等词的简称〔口语〕','事情还没开始，先把自己鼓动起来，或设法让对手在心里乱了阵脚。','psych 是一组心理相关长词的截短形式；名词、动词的具体来源分支不同，不能都当成直接借入古希腊的同一个动词。',Y,'psych yourself up 是给自己鼓劲；psych someone out 常是让对方心理受干扰、失去信心。课程表或口语中的 psych class 则可能是心理学课。这个短词的意思很依赖后面的 up、out 和使用场景。','psych yourself up；psych someone out；a psych class。','psych up 主要把心理状态调到准备迎战；psych out 常让别人紧张或乱了判断。不要把两者方向记反。',('She listened to music to psych herself up before the race.','比赛前，她听音乐给自己鼓劲。'),('He tried to psych his opponent out by acting completely relaxed.','他装得非常轻松，想让对手在心理上乱了阵脚。'),('I have a psych class on Tuesday.','我周二有一节心理学课。'),sources=['https://en.wiktionary.org/wiki/psych']),
E('psyched','/saɪkt/','兴奋期待的；已作好心理准备的；psych 的过去式和过去分词','心里已经热起来，觉得“好，来吧，我准备好了”。','psych + -ed；/k/ 后的词尾读 /t/，不是读出一个额外的 /ɪd/。',H(Y,'英语 psych → psyched','调整心理状态 → 已鼓起劲、兴奋准备好的'),'I’m psyched about the trip 是对旅行很兴奋期待。psyched up 常强调鼓劲准备；psyched out 却可能表示被吓住或心理受干扰。要连同小词一起读，不能只把 psyched 固定成“开心”。','be psyched about；get psyched up；feel psyched。','excited 是更通用的兴奋；psyched 很口语，常带已经在心理上投入、准备行动的感觉。',('I’m really psyched about our first concert.','我对我们的首场演出特别兴奋。'),('The team was psyched up and ready to play.','全队都鼓足了劲，准备上场。'),sources=['https://en.wiktionary.org/wiki/psyched','https://en.wiktionary.org/wiki/psych']),
E('psyching','/ˈsaɪkɪŋ/','正在鼓劲、作心理准备或施加心理影响','把镜头停在出发前：人正在调动情绪、建立信心，或者扰乱对手的心理。','psych + -ing；保留 ch，在这里仍读 /k/。',H(Y,'英语 psych → psyching','影响、准备心理状态 → 正在进行这个过程'),'psyching herself up 描写给自己打气的过程；psyching the others out 则说正在让别人不安。这个 -ing 形式不会改变 up 和 out 的区别，先找完整搭配再判断动作的方向。','psyching myself up；psyching an opponent out。','psyched 常看已形成的状态；psyching 更突出调动或影响心理的过程。',('He was psyching himself up for the interview.','他正在为面试给自己鼓劲。'),('The players accused each other of psyching the opposition out.','球员们互相指责对方在用心理战干扰对手。'),sources=['https://en.wiktionary.org/wiki/psych','https://www.merriam-webster.com/dictionary/psych']),
E('psycho','英 /ˈsaɪkəʊ/；美 /ˈsaɪkoʊ/','“疯子、变态”等贬称〔口语，常冒犯〕','说话人把一个让他害怕、愤怒或无法理解的人，粗暴地压成一个带攻击性的标签。','由 psychotic、psychopath 等词截短，或与口语人物词尾 -o 相结合；这里是独立俚语，不等于中性的构词成分 psycho-。',G+[['英语 psychotic／psychopath 等词的口语截短','精神健康或人格相关术语被粗略缩短'],['英语 psycho','对人的贬称；不精确的口语标签']],'影视台词里的 psycho 常是辱骂，不是准确诊断。学习它主要是为了听懂语气。psycho- 在 psychology、psychoanalysis 等长词里通常只表示心灵或心理，不能因此把所有这类词都理解成骂人。','call someone a psycho；use psycho as an insult。','psycho 的口语攻击性与 psych“给自己鼓劲”等普通搭配不同，也不能替代任何专业诊断名。',('The editor removed the word “psycho” because it turned a description into an insult.','编辑删去了 psycho 一词，因为它把描述变成了辱骂。'),('The film uses “psycho” as a hostile label, not as a precise diagnosis.','影片把 psycho 当作敌意标签使用，并非精确的诊断名称。'),sources=['https://en.wiktionary.org/wiki/psycho','https://www.etymonline.com/word/psycho']),
E('psychologically','英 /ˌsaɪkəˈlɒdʒɪkli/；美 /ˌsaɪkəˈlɑːdʒɪkli/','在心理上；从心理学角度','同一件事，身体上可能能做，心里却未必已经准备好；这里关注的是后一层。','psychological + -ly，读音中 -cal- 通常压缩为 /k/ 接 /li/。',G+[['近代 psychology → 英语 psychological','心理学 → 心理的、心理学的'],['英语 psychologically','从心理层面或心理学角度']],'psychologically demanding 是心理负担很重；psychologically prepared 是心理上作好准备。它也能说明一种解释角度，如从心理学角度分析人物，不等于说事情是“假想出来的”。','psychologically prepared；psychologically demanding；psychologically important。','physically 侧重身体或物理层面；psychologically 侧重感受、认知和心理状态。二者常互相影响。',('The journey was physically easy but psychologically demanding.','这趟旅程体力上不难，心理上却很费劲。'),('She felt psychologically prepared for the change.','她觉得自己已经为这个变化作好了心理准备。'),sources=['https://en.wiktionary.org/wiki/psychologically']),
E('psychiatry','/saɪˈkaɪətri/','精神医学；精神病学','把情绪、思维和行为方面的困难放到医学里研究，进行评估、诊治和预防。','psyche“心灵”与希腊医学构词材料 iatros／iatreia 相连；英语与法语 psychiatrie 等近代术语相接。',J,'psychiatry 是医学的一支，研究范围不只某一种严重疾病。读医院科室名 department of psychiatry，可以直接理解成精神科。不要因为中文里有“精神病”三个字，就把它想成只处理影视里极端失控的情况。','study psychiatry；a department of psychiatry；child psychiatry。','psychology 是研究心理与行为的更广领域；psychiatry 明确属于医学。两者会合作，也各有训练路径。',('After medical school, she chose to specialize in psychiatry.','医学院毕业后，她选择专攻精神医学。'),('The hospital has a separate department of psychiatry.','这家医院设有独立的精神科。'),sources=['https://www.merriam-webster.com/dictionary/psychiatry','https://www.etymonline.com/word/psychiatry','https://www.psychiatry.org/patients-families/what-is-psychiatry']),
E('psychiatrist','/saɪˈkaɪətrɪst/','精神科医生','这位专业人员首先有医学医生的训练，再专门处理心理、情绪和行为相关的医学问题。','与 psychiatry 对应，用 -ist 表示从事这一医学专业的人。',H(J,'英语 psychiatry → psychiatrist','精神医学 → 精神科医生'),'psychiatrist 可以进行医学评估，并根据专业范围开展药物治疗、心理治疗等工作。这个称呼的关键是医生背景。仅凭心理学博士学位不能自动等同于 psychiatrist，具体职业资格也要看所在地区。','see a psychiatrist；consultant psychiatrist；a child psychiatrist。','psychiatrist 是医学专业的精神科医生；psychologist 按心理学专业训练与工作来命名。两种职业并非简单的高低关系。',('The psychiatrist asked about both his sleep and his mood.','精神科医生询问了他的睡眠和情绪情况。'),('A psychiatrist and a psychologist worked together on the research team.','一位精神科医生和一位心理学家在这个研究团队中合作。'),sources=['https://en.wiktionary.org/wiki/psychiatrist','https://www.psychiatry.org/patients-families/what-is-psychiatry']),
E('psychiatric','/ˌsaɪkiˈætrɪk/','精神医学的；精神科的','给某个服务、评估或研究标明范围：它属于精神医学这一专业。','与 psychiatry 对应的 -ic 形容词形式；词尾转换后重音和元音随之变化。',H(J,'英语 psychiatry → psychiatric','精神医学 → 精神医学方面的'),'psychiatric assessment 是精神科评估；psychiatric services 是相关医疗服务。这个形容词修饰的是专业范围，不能只凭它就推断某人的具体症状、严重程度或危险性。','psychiatric care；a psychiatric assessment；psychiatric research。','psychiatric 明确与精神医学有关；psychological 可以说更广泛的心理因素，不一定涉及医学诊断。',('The clinic expanded its psychiatric services.','诊所扩充了精神科服务。'),('The report describes the purpose of the psychiatric assessment.','报告说明了这次精神科评估的目的。'),sources=['https://www.merriam-webster.com/dictionary/psychiatry','https://en.wiktionary.org/wiki/psychiatric','https://www.psychiatry.org/patients-families/what-is-psychiatry']),
]
